const search=document.getElementById('tool-search'),cards=[...document.querySelectorAll('.tool-card')],filters=[...document.querySelectorAll('.filter')];let category='All tools';
function apply(){let count=0;const q=search.value.trim().toLowerCase();for(const card of cards){const show=(category==='All tools'||card.dataset.category===category)&&card.dataset.search.includes(q);card.hidden=!show;if(show)count++;}for(const f of filters)f.setAttribute('aria-pressed',String(f.dataset.category===category));document.getElementById('no-results').hidden=count>0;document.getElementById('tool-count').textContent=`${count} tools. One simpler workflow.`;}
search.addEventListener('input',apply);for(const f of filters)f.onclick=()=>{category=f.dataset.category;apply();};for(const a of document.querySelectorAll('[data-filter-link]'))a.onclick=()=>{category=a.dataset.filterLink;search.value='';apply();};window.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){e.preventDefault();search.focus();}});
